// Helper: Simple Icons URL
const logo = (slug) => `https://cdn.simpleicons.org/${slug}`

// Tool counter continuing from existing 30 tools
let toolNum = 30
let catId = ''

const newTools = []

function addTool(cat, slug, name, descEs, descEn, priceModel, priceStart, rating, openSource, tags, founded, website) {
  toolNum++
  catId = cat
  return {
    id: `tool-${toolNum}`, slug, name,
    logo_url: logo(slug),
    description_es: descEs, description_en: descEn,
    category_id: cat, price_model: priceModel, price_starting: priceStart,
    website_url: website || `https://${slug}.com`, affiliate_url: null,
    rating_g2: rating || null, rating_capterra: null,
    is_open_source: openSource || false, is_verified: false, listing_tier: 'free',
    tags: tags || [],
    alternatives: []
  }
}

